SELECT CASE WHEN d.budget >= 3067000 THEN 'high' WHEN d.budget >= 1964000 THEN 'mid' ELSE 'low' END AS budget_bucket, d.dept_name, COUNT(CASE WHEN e.job_title = 'Director' THEN 1 END) AS director_count FROM employees e LEFT OUTER JOIN departments d ON e.dept_id = d.id WHERE d.dept_name IN ('Marketing', 'Legal') GROUP BY CASE WHEN d.budget >= 3067000 THEN 'high' WHEN d.budget >= 1964000 THEN 'mid' ELSE 'low' END, d.dept_name;
